package de.terrestris.shoguncore.dao;

import java.util.Objects;

/**
 * A sort order of a DAO query: a property name and a direction.
 * <p>
 * This replaces the legacy (and in Hibernate 6 removed)
 * <code>org.hibernate.criterion.Order</code> in the DAO and service API.
 */
public final class SortOrder {

    /**
     * The name of the property to sort by.
     */
    private final String property;

    /**
     * Whether to sort ascending (or descending).
     */
    private final boolean ascending;

    /**
     * @param property  The name of the property to sort by.
     * @param ascending Whether to sort ascending (or descending).
     */
    private SortOrder(String property, boolean ascending) {
        if (property == null) {
            throw new IllegalArgumentException("The property of a sort order must not be null");
        }
        this.property = property;
        this.ascending = ascending;
    }

    /**
     * Creates an ascending sort order on the given property.
     *
     * @param property The name of the property to sort by.
     * @return The sort order.
     */
    public static SortOrder asc(String property) {
        return new SortOrder(property, true);
    }

    /**
     * Creates a descending sort order on the given property.
     *
     * @param property The name of the property to sort by.
     * @return The sort order.
     */
    public static SortOrder desc(String property) {
        return new SortOrder(property, false);
    }

    /**
     * @return The name of the property to sort by.
     */
    public String getProperty() {
        return property;
    }

    /**
     * @return <code>true</code> if the sort order is ascending,
     * <code>false</code> if it is descending.
     */
    public boolean isAscending() {
        return ascending;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof SortOrder)) {
            return false;
        }
        SortOrder other = (SortOrder) obj;
        return ascending == other.ascending && property.equals(other.property);
    }

    @Override
    public int hashCode() {
        return Objects.hash(property, ascending);
    }

    @Override
    public String toString() {
        return property + (ascending ? " asc" : " desc");
    }
}
