package de.terrestris.shoguncore.hibernate;

import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import org.joda.time.LocalDate;

/**
 * A JPA converter that persists Joda {@link LocalDate}s as SQL dates.
 * <p>
 * This replaces the <code>org.jadira.usertype.dateandtime.joda.PersistentLocalDate</code>
 * user type, which is not available for Hibernate 6.
 */
@Converter
public class JodaLocalDateConverter implements AttributeConverter<LocalDate, java.time.LocalDate> {

    @Override
    public java.time.LocalDate convertToDatabaseColumn(LocalDate attribute) {
        if (attribute == null) {
            return null;
        }
        return java.time.LocalDate.of(attribute.getYear(), attribute.getMonthOfYear(), attribute.getDayOfMonth());
    }

    @Override
    public LocalDate convertToEntityAttribute(java.time.LocalDate dbData) {
        if (dbData == null) {
            return null;
        }
        return new LocalDate(dbData.getYear(), dbData.getMonthValue(), dbData.getDayOfMonth());
    }
}
