import re, sys, os

ASSERTS2 = {'assertTrue', 'assertFalse', 'assertNull', 'assertNotNull'}
ASSERTS3 = {'assertEquals', 'assertNotEquals', 'assertSame', 'assertNotSame', 'assertArrayEquals'}
review = []

def find_close(s, i):
    """s[i] == '(' -> index of matching ')' (string/char aware)."""
    depth = 0
    j = i
    while j < len(s):
        c = s[j]
        if c == '"' or c == "'":
            q = c; j += 1
            while s[j] != q:
                if s[j] == '\\': j += 1
                j += 1
        elif c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
            if depth == 0:
                return j
        j += 1
    raise ValueError('unbalanced')

def split_args(a):
    args, depth, cur, j = [], 0, '', 0
    while j < len(a):
        c = a[j]
        if c == '"' or c == "'":
            q = c; k = j + 1
            while a[k] != q:
                if a[k] == '\\': k += 1
                k += 1
            cur += a[j:k+1]; j = k + 1; continue
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
        elif c == '<' and j > 0 and re.match(r'[A-Za-z0-9_]', a[j-1]) and re.match(r'[A-Z?]', a[j+1:j+2] or ' '):
            depth += 1
        elif c == '>' and depth > 0 and j > 0 and re.match(r'[A-Za-z0-9_?>\]]', a[j-1]):
            depth -= 1
        if c == ',' and depth == 0:
            args.append(cur); cur = ''
        else:
            cur += c
        j += 1
    args.append(cur)
    return args

def is_stringish(arg):
    a = arg.strip()
    return a.startswith('"') or re.search(r'"\s*\+|\+\s*"', a) is not None or a.startswith('String.format')

def move_msg(args):
    # move first arg to the end, keep whitespace sensible
    msg = args[0].strip()
    rest = args[1:]
    rest[0] = rest[0].lstrip()
    if rest[0].startswith('\n'):
        pass
    return rest + [' ' + msg]

def fix_asserts(s, fname):
    out, i = [], 0
    pat = re.compile(r'\b((?:Assert|Assertions)\.)?(assert[A-Za-z]+)\(')
    while True:
        m = pat.search(s, i)
        if not m:
            out.append(s[i:]); break
        name = m.group(2)
        open_idx = m.end() - 1
        close_idx = find_close(s, open_idx)
        inner = s[open_idx+1:close_idx]
        inner = fix_asserts(inner, fname)  # nested
        args = split_args(inner)
        prefix = m.group(1) or ''
        if prefix:
            prefix = 'MatcherAssert.' if name == 'assertThat' else 'Assertions.'
        new_args = args
        if name in ASSERTS2 and len(args) == 2:
            new_args = move_msg(args)
        elif name in ASSERTS3 and len(args) == 4:
            new_args = move_msg(args)
        elif name in ASSERTS3 and len(args) == 3:
            if is_stringish(args[0]):
                new_args = move_msg(args)
            else:
                review.append('%s: %s(%s)' % (fname, name, inner.strip()[:150]))
        out.append(s[i:m.start()] + prefix + name + '(' + ','.join(new_args) + ')')
        i = close_idx + 1
    return ''.join(out)

def fix_expected(s):
    pat = re.compile(r'@Test\(\s*expected\s*=\s*([A-Za-z0-9_.]+)\.class\s*\)')
    while True:
        m = pat.search(s)
        if not m:
            return s
        exc = m.group(1)
        brace = s.index('{', m.end())
        # find matching close brace
        depth, j = 0, brace
        while True:
            c = s[j]
            if c == '"':
                j += 1
                while s[j] != '"':
                    if s[j] == '\\': j += 1
                    j += 1
            elif c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0: break
            j += 1
        body = s[brace+1:j]
        # indentation of the method
        line_start = s.rfind('\n', 0, m.start()) + 1
        indent = s[line_start:m.start()]
        body_lines = body.strip('\n').split('\n')
        new_body = '\n'.join(('    ' + l) if l.strip() else l for l in body_lines)
        new = ('{\n' + indent + '    assertThrows(' + exc + '.class, () -> {\n' + new_body + '\n'
               + indent + '    });\n' + indent + '}')
        s = s[:m.start()] + '@Test' + s[m.end():brace] + new + s[j+1:]

IMPORTS = [
    (r'import org\.junit\.Test;', 'import org.junit.jupiter.api.Test;'),
    (r'import org\.junit\.Before;', 'import org.junit.jupiter.api.BeforeEach;'),
    (r'import org\.junit\.After;', 'import org.junit.jupiter.api.AfterEach;'),
    (r'import org\.junit\.BeforeClass;', 'import org.junit.jupiter.api.BeforeAll;'),
    (r'import org\.junit\.AfterClass;', 'import org.junit.jupiter.api.AfterAll;'),
    (r'import org\.junit\.Assert;', 'import org.junit.jupiter.api.Assertions;'),
    (r'import static org\.junit\.Assert\.assertThat;', 'import static org.hamcrest.MatcherAssert.assertThat;'),
    (r'import static org\.junit\.Assert\.', 'import static org.junit.jupiter.api.Assertions.'),
    (r'import org\.junit\.runner\.RunWith;', 'import org.junit.jupiter.api.extension.ExtendWith;'),
    (r'import org\.springframework\.test\.context\.junit4\.SpringJUnit4ClassRunner;',
     'import org.springframework.test.context.junit.jupiter.SpringExtension;'),
    (r'import (static )?org\.mockito\.Matchers\b', r'import \1org.mockito.ArgumentMatchers'),
]

def convert(path):
    s = open(path).read()
    orig = s
    for a, b in IMPORTS:
        s = re.sub(a, b, s)
    s = re.sub(r'@Before(?![A-Za-z])', '@BeforeEach', s)
    s = re.sub(r'@After(?![A-Za-z])', '@AfterEach', s)
    s = re.sub(r'@BeforeClass\b', '@BeforeAll', s)
    s = re.sub(r'@AfterClass\b', '@AfterAll', s)
    s = s.replace('@RunWith(SpringJUnit4ClassRunner.class)', '@ExtendWith(SpringExtension.class)')
    s = re.sub(r'\bMatchers\.', 'ArgumentMatchers.', s)
    s = re.sub(r'\banyCollectionOf\([^)]*\)', 'anyCollection()', s)
    s = s.replace('import static org.mockito.ArgumentMatchers.anyCollectionOf;', 'import static org.mockito.ArgumentMatchers.anyCollection;')
    s = s.replace('MockitoAnnotations.initMocks(', 'MockitoAnnotations.openMocks(')
    s = s.replace('verifyZeroInteractions', 'verifyNoInteractions')
    had_expected = '@Test(expected' in s
    s = fix_expected(s)
    s = fix_asserts(s, os.path.basename(path))
    # imports needed
    def add_import(s, imp):
        if imp in s:
            return s
        idx = s.index('\nimport ')
        return s[:idx] + '\n' + imp + s[idx:]
    if had_expected and 'org.junit.jupiter.api.Assertions.*;' not in s:
        s = add_import(s, 'import static org.junit.jupiter.api.Assertions.assertThrows;')
    if 'MatcherAssert.assertThat' in s:
        s = add_import(s, 'import org.hamcrest.MatcherAssert;')
    if re.search(r'(?<![.\w])assertThat\(', s) and 'import static org.hamcrest.MatcherAssert.assertThat;' not in s:
        s = add_import(s, 'import static org.hamcrest.MatcherAssert.assertThat;')
    if s != orig:
        open(path, 'w').write(s)

for root, _, files in os.walk(sys.argv[1]):
    for f in files:
        if f.endswith('.java'):
            convert(os.path.join(root, f))
print('\n'.join(review))
EOF
