    @Test
    public void findAllWithCollectionContaining_commonUsage() {

        List<Plugin> pluginsP1andP2 = new ArrayList<>();
        List<Plugin> pluginsP2andP3 = new ArrayList<>();

        Plugin p1 = new Plugin();
        p1.setName("p1");
