package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.Application;
import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.Plugin;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.layer.source.ImageWmsLayerDataSource;
import de.terrestris.shoguncore.model.layer.source.LayerDataSource;
import de.terrestris.shoguncore.model.layer.source.WfsLayerDataSource;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.model.security.PermissionCollection;
import de.terrestris.shoguncore.paging.PagingResult;
import jakarta.persistence.criteria.Root;
import org.hibernate.NonUniqueResultException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the behaviour of the {@link GenericHibernateDao} query methods that
 * accept {@link QueryRestriction}s and {@link SortOrder}s.
 */
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class GenericHibernateDaoQueryRestrictionTest {

    @Autowired
    AppTestDao appDao;

    @Autowired
    PluginTestDao pluginDao;

    @Autowired
    @Qualifier("userDao")
    UserDao<User> userDao;

    @Autowired
    @Qualifier("permissionCollectionDao")
    PermissionCollectionDao<PermissionCollection> permissionCollectionDao;

    @Autowired
    @Qualifier("layerDataSourceDao")
    LayerDataSourceDao<LayerDataSource> layerDataSourceDao;

    private Application saveApp(String name, String description) {
        Application app = new Application(name, description);
        appDao.saveOrUpdate(app);
        return app;
    }

    private static QueryRestriction<Application> nameEquals(String name) {
        return (root, query, cb) -> cb.equal(root.get("name"), name);
    }

    @Test
    public void findByUniqueCriteria_returnsNullIfNothingMatches() {
        saveApp("a1", "d1");

        assertNull(appDao.findByUniqueCriteria(nameEquals("does-not-exist")));
    }

    @Test
    public void findByUniqueCriteria_returnsTheMatchingEntity() {
        Application a1 = saveApp("a1", "d1");
        saveApp("a2", "d2");

        assertSame(a1, appDao.findByUniqueCriteria(nameEquals("a1")));
    }

    @Test
    public void findByUniqueCriteria_throwsIfMoreThanOneEntityMatches() {
        saveApp("a1", "d1");
        saveApp("a1", "d2");

        assertThrows(NonUniqueResultException.class, () -> appDao.findByUniqueCriteria(nameEquals("a1")));
    }

    @Test
    @SuppressWarnings("unchecked")
    public void findByCriteria_treatsNullOrEmptyRestrictionsAsNoRestriction() {
        saveApp("a1", "d1");
        saveApp("a2", "d2");

        assertEquals(2, appDao.findByCriteria((QueryRestriction<Application>[]) null).size());
        assertEquals(2, appDao.findByCriteria(new QueryRestriction[0]).size());
        assertEquals(2, appDao.findByCriteria((root, query, cb) -> null).size());
    }

    @Test
    public void findByCriteria_combinesRestrictionsWithAnd() {
        saveApp("a1", "d1");
        saveApp("a1", "d2");
        saveApp("a2", "d1");

        QueryRestriction<Application> descIsD1 = (root, query, cb) -> cb.equal(root.get("description"), "d1");

        List<Application> result = appDao.findByCriteria(nameEquals("a1"), descIsD1);

        assertEquals(1, result.size());
        assertEquals("a1", result.get(0).getName());
        assertEquals("d1", result.get(0).getDescription());
    }

    @Test
    public void findByCriteria_returnsDistinctRootEntitiesForJoiningRestrictions() {
        Plugin p1 = new Plugin();
        p1.setName("p1");
        p1.setClassName("p1");
        Plugin p2 = new Plugin();
        p2.setName("p2");
        p2.setClassName("p2");
        pluginDao.saveOrUpdate(p1);
        pluginDao.saveOrUpdate(p2);

        Application app = new Application("a1", "d1");
        app.setPlugins(Arrays.asList(p1, p2));
        appDao.saveOrUpdate(app);

        // the join matches the application twice
        QueryRestriction<Application> hasPlugins = (root, query, cb) ->
            cb.isNotNull(root.join("plugins").get("id"));

        List<Application> result = appDao.findByCriteria(hasPlugins);
        assertEquals(1, result.size());
        assertSame(app, result.get(0));

        assertEquals(1L, appDao.getTotalCount(hasPlugins).longValue());
    }

    @Test
    public void findByCriteriaRestricted_setsOnlyTheRequestedFields() {
        Application a1 = saveApp("a1", "d1");
        saveApp("a2", "d2");

        List<Application> result = appDao.findByCriteriaRestricted(Arrays.asList("id", "name"), nameEquals("a1"));

        assertEquals(1, result.size());
        Application restricted = result.get(0);
        assertEquals(a1.getId(), restricted.getId());
        assertEquals("a1", restricted.getName());
        assertNull(restricted.getDescription());
        assertNull(restricted.getCreated());
    }

    @Test
    public void findByCriteriaRestricted_returnsFullEntitiesWithoutFieldList() {
        Application a1 = saveApp("a1", "d1");
        saveApp("a2", "d2");

        List<Application> all = appDao.findByCriteriaRestricted(null);
        assertEquals(2, all.size());

        List<Application> result = appDao.findByCriteriaRestricted(null, nameEquals("a1"));
        assertEquals(1, result.size());
        assertSame(a1, result.get(0));
        assertEquals("d1", result.get(0).getDescription());
    }

    @Test
    public void getTotalCount_countsMatchingEntities() {
        saveApp("a1", "d1");
