package de.terrestris.shoguncore.hibernate;

import org.hibernate.boot.model.TypeContributions;
import org.hibernate.dialect.PostgreSQLDialect;
import org.hibernate.service.ServiceRegistry;
import org.hibernate.type.descriptor.sql.internal.DdlTypeImpl;
import org.hibernate.type.descriptor.sql.spi.DdlTypeRegistry;

import java.sql.Types;

/**
 * A PostgreSQL dialect that maps {@link Types#OTHER} (as used by the
 * {@link JsonbUserType}) to <code>jsonb</code>.
 * <p>
 * Since Hibernate 6, the spatial (PostGIS) support is contributed to the
 * standard {@link PostgreSQLDialect} by <code>hibernate-spatial</code>, so
 * there is no need to extend a dedicated PostGIS dialect anymore.
 */
public class ShogunPostgresqlDialect extends PostgreSQLDialect {

    private static final long serialVersionUID = 9177170273858773475L;

    public ShogunPostgresqlDialect() {
        super();
    }

    /**
     * Registers <code>jsonb</code> as the column type for {@link Types#OTHER}.
     */
    @Override
    protected void registerColumnTypes(TypeContributions typeContributions, ServiceRegistry serviceRegistry) {
        super.registerColumnTypes(typeContributions, serviceRegistry);

        final DdlTypeRegistry ddlTypeRegistry = typeContributions.getTypeConfiguration().getDdlTypeRegistry();
