package de.terrestris.shoguncore.util.dialect;

import de.terrestris.shoguncore.hibernate.ShogunPostgresqlDialect;
import org.hibernate.boot.Metadata;
import org.hibernate.boot.MetadataSources;
import org.hibernate.boot.registry.StandardServiceRegistry;
import org.hibernate.boot.registry.StandardServiceRegistryBuilder;
import org.hibernate.cfg.AvailableSettings;
import org.hibernate.dialect.Dialect;
import org.hibernate.type.descriptor.sql.spi.DdlTypeRegistry;
import org.junit.jupiter.api.Test;

import java.sql.Types;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the column types registered by the custom SHOGun-Core dialects.
 */
public class ShogunDialectColumnTypesTest {

    /**
     * Bootstraps the Hibernate metadata (without a database connection) for
     * the given dialect and returns the resulting DDL type registry.
     */
    private static DdlTypeRegistry getDdlTypeRegistry(Class<? extends Dialect> dialectClass) {
        StandardServiceRegistry registry = new StandardServiceRegistryBuilder()
            .applySetting(AvailableSettings.DIALECT, dialectClass.getName())
            .applySetting("hibernate.temp.use_jdbc_metadata_defaults", "false")
            .build();
        try {
            Metadata metadata = new MetadataSources(registry).buildMetadata();
            return metadata.getDatabase().getTypeConfiguration().getDdlTypeRegistry();
        } finally {
            StandardServiceRegistryBuilder.destroy(registry);
        }
    }

    @Test
    public void postgresqlDialectMapsOtherToJsonb() {
        DdlTypeRegistry ddlTypeRegistry = getDdlTypeRegistry(ShogunPostgresqlDialect.class);

        assertEquals("jsonb", ddlTypeRegistry.getDescriptor(Types.OTHER).getRawTypeName());
        // the standard mappings are still available
        assertEquals("varchar", ddlTypeRegistry.getDescriptor(Types.VARCHAR).getRawTypeName());
    }

    @Test
    public void oracleDialectMapsLargeObjectTypes() {
        DdlTypeRegistry ddlTypeRegistry = getDdlTypeRegistry(ShogunCoreOracleDialect.class);

        assertEquals("blob", ddlTypeRegistry.getDescriptor(Types.VARBINARY).getRawTypeName());
        assertEquals("clob", ddlTypeRegistry.getDescriptor(Types.LONGVARCHAR).getRawTypeName());
        assertEquals("long raw", ddlTypeRegistry.getDescriptor(Types.LONGVARBINARY).getRawTypeName());
        assertTrue(ddlTypeRegistry.getDescriptor(Types.VARCHAR).getRawTypeName().startsWith("varchar2"));
    }
}
