package de.terrestris.shoguncore.util.dialect;

import org.hibernate.boot.model.TypeContributions;
import org.hibernate.dialect.Dialect;
import org.hibernate.dialect.OracleDialect;
import org.hibernate.service.ServiceRegistry;
import org.hibernate.type.descriptor.sql.internal.DdlTypeImpl;
import org.hibernate.type.descriptor.sql.spi.DdlTypeRegistry;

import java.sql.Types;

/**
 * SQL {@link Dialect} extending {@link OracleDialect} to register
 * column mapping for LOB datatypes used in SHOGun-Core (e.g. file content
 * in {@link de.terrestris.shoguncore.model.File})
 *
 * @author Andre Henn
 * @author terrestris GmbH & co. KG
 */
public class ShogunCoreOracleDialect extends OracleDialect {

    /**
     * The DDL type registry the column types are currently registered in
     * (only set while {@link #registerColumnTypes(TypeContributions, ServiceRegistry)}
     * is running).
     */
    private transient DdlTypeRegistry ddlTypeRegistry;

    /**
     *
     */
    public ShogunCoreOracleDialect() {
        super();
    }

    /**
     * Registers the column types of the Oracle dialect and the large object
     * types used in SHOGun-Core (see {@link #registerLargeObjectTypeMappings()}).
     */
    @Override
    protected void registerColumnTypes(TypeContributions typeContributions, ServiceRegistry serviceRegistry) {
        super.registerColumnTypes(typeContributions, serviceRegistry);

        this.ddlTypeRegistry = typeContributions.getTypeConfiguration().getDdlTypeRegistry();
        try {
            registerLargeObjectTypeMappings();
        } finally {
            this.ddlTypeRegistry = null;
        }
    }

    /**
     * Registers the column types for the large object types used in
     * SHOGun-Core. This is called while the column types of the dialect are
     * registered, subclasses may override this (and call super).
     */
    protected void registerLargeObjectTypeMappings() {
        if (ddlTypeRegistry == null) {
            return;
        }
        ddlTypeRegistry.addDescriptor(new DdlTypeImpl(Types.VARBINARY, "blob", this));
        ddlTypeRegistry.addDescriptor(new DdlTypeImpl(Types.LONGVARCHAR, "clob", this));
        ddlTypeRegistry.addDescriptor(new DdlTypeImpl(Types.LONGVARBINARY, "long raw", this));
    }
}
